(201, 1,  '帮忙代取快递送到宿舍楼下', 'errand', '两个小件快递，在韵苑菜鸟驿站，取件码稍后私信。送到 12 栋楼下即可。', 8,  '今天 18:00 前', '华中科技大学韵苑 12 栋', 30.5172, 114.4266, 'pending',  '2026-09-23 09:10:00'),
(202, 10, '借一把民谣吉他（周末两天）', 'borrow', '社团小型演出临时借用，周六取周日还，如有琴包更好，会小心保管。', 15, '本周六前',     '华中科技大学紫菘学生公寓', 30.5088, 114.4243, 'pending',  '2026-09-23 08:30:00'),
(203, 9,  '求教高数第三章课后习题', 'qa',     '多元函数微分学部分，第 12、15、18 题没思路，希望能当面讲一遍。', 20, '本周内',       '华中科技大学图书馆三楼研讨间', 30.5138, 114.4298, 'ongoing',  '2026-09-22 20:15:00'),
(204, 1,  '帮忙搬运两箱行李上 6 楼', 'carry',  '两箱书和衣物，无电梯，宿舍在 6 楼。已备好矿泉水。', 30, '已完成',       '华中科技大学西十二舍', 30.5148, 114.4229, 'finished', '2026-09-19 15:40:00'),
(205, 11, '求带一份材料到行政楼盖章', 'errand', '社团活动备案表，需要教务处与学工处两个章，跑一趟即可，材料已装袋。', 10, '明天上午',     '华中科技大学行政楼', 30.5104, 114.4308, 'ongoing',  '2026-09-22 16:20:00'),
(206, 12, '借一个充电宝救急', 'borrow', '在东九上晚课，手机剩 5% 电，求借一个充电宝用到 21:30。', 5,  '今晚 22:00 前', '华中科技大学东九教学楼', 30.5162, 114.4341, 'pending',  '2026-09-23 11:05:00'),
(207, 13, '求帮修改一份英文简历', 'skill',  '申请海外交换项目用的 CV，希望帮忙润色措辞并调整结构。', 25, '已完成',       '线上沟通', 0, 0, 'finished', '2026-09-15 10:00:00'),
(208, 10, '帮忙照看半天仓鼠', 'skill',  '国庆回家一天，需要有人帮忙喂食换水，笼子在我宿舍，操作很简单。', 18, '国庆期间',     '华中科技大学韵苑 8 栋', 30.5181, 114.4258, 'pending',  '2026-09-23 10:20:00'),
(209, 2,  '求借一套正装参加答辩', 'borrow', '周四答辩需要正装一套，女生 M 码，穿一天即还。', 12, '本周四前', '华中科技大学紫菘学生公寓', 30.5088, 114.4243, 'pending',  '2026-09-23 13:00:00'),
(210, 15, '求帮忙调试单片机小车轮', 'skill', '循迹小车总跑偏，怀疑是 PID 参数，求大佬远程或现场指导。', 22, '本周内', '华中科技大学光电大楼', 30.5135, 114.4342, 'pending',  '2026-09-23 13:20:00'),
(211, 3,  '帮忙搬三桶饮用水上楼', 'carry', '三桶桶装水已送到楼下小卖部，求人搭把手搬上 3 楼。', 12, '今天 21:00 前', '华中科技大学西十二舍', 30.5148, 114.4229, 'finished', '2026-09-22 10:00:00'),
(212, 17, '求答疑 C 语言指针与结构体', 'qa', '期末复习卡在指针与结构体嵌套，求一次一对一答疑。', 18, '本周内', '华中科技大学图书馆二楼自习区', 30.5140, 114.4300, 'finished', '2026-09-21 19:00:00');
